import {getTravelTrips,tripName,commitTravelTrip} from './trip-model.js?v=20261018-mont-saint-michel';
import {localPlaceMatches,searchOnlinePlaces} from './place-search.js?v=20261018-mont-saint-michel';
import {findDestinationPin} from './destination-picker.js?v=20261018-mont-saint-michel';
import {placeGuideHref} from './place-media.js?v=20261018-mont-saint-michel';
import {toTraditional} from './i18n.js?v=20261018-mont-saint-michel';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderTravelTrips(){return `<section class="travel-trips" data-travel-trips><div class="trip-section-heading"><div><span class="section-kicker mono">JOURNEYS & MEMORIES</span><h2>行程记录</h2></div><button type="button" class="map-add" data-trip-new>＋ 新建行程</button></div><p class="trip-help">按年份与地区命名，记录同一段旅途中的城市与评分。</p><div data-trip-list></div><p data-trip-message role="status"></p><dialog class="trip-dialog" data-trip-dialog aria-labelledby="trip-dialog-title"><form data-trip-form><div class="trip-dialog-top"><span class="mono">A JOURNEY TO REMEMBER</span><button type="button" data-trip-close aria-label="关闭行程编辑">×</button></div><h2 id="trip-dialog-title">新建行程</h2><div class="trip-name-fields"><label>年份<input name="year" type="number" min="1900" max="9999" required></label><label>地区<input name="region" maxlength="80" placeholder="例如：台湾、瑞士、日本关西" required></label></div><p class="trip-name-preview" data-trip-name data-i18n-skip></p><label class="trip-city-search">添加城市<input type="search" data-trip-query placeholder="搜索已收藏或其他城市…" autocomplete="off"></label><button type="button" class="text-link" data-trip-search>搜索更多城市</button><div class="trip-city-results" data-trip-results></div><h3>本次行程的城市</h3><p class="trip-help">每个城市必须点击推荐星级，保存后自动标为去过。</p><div data-trip-stops></div><p class="trip-error" data-trip-feedback role="status"></p><div class="trip-form-actions"><button type="button" class="text-link" data-trip-close>取消</button><button type="submit" class="map-add" data-trip-save>保存行程</button></div></form></dialog></section>`;}
export function mountTravelTrips(root,{getPins,onSave,onChanged=()=>{}}){
  const panel=root.querySelector('[data-travel-trips]');if(!panel)return ()=>{};
  const dialog=panel.querySelector('[data-trip-dialog]'),form=panel.querySelector('[data-trip-form]'),query=panel.querySelector('[data-trip-query]'),results=panel.querySelector('[data-trip-results]'),stopsHost=panel.querySelector('[data-trip-stops]'),feedback=panel.querySelector('[data-trip-feedback]'),message=panel.querySelector('[data-trip-message]'),save=panel.querySelector('[data-trip-save]');
  let draft,choices=[],remote=[],controller,revision=0,saving=false,stopped=false;
  const key=value=>toTraditional(String(value||'')).toLowerCase();
  function drawList(){const trips=getTravelTrips().slice().sort((a,b)=>b.year-a.year||a.region.localeCompare(b.region));panel.querySelector('[data-trip-list]').innerHTML=trips.length?trips.map(trip=>`<article class="trip-record"><div class="trip-record-heading"><h3 data-i18n-skip>${esc(tripName(trip))}</h3><button type="button" class="text-link" data-trip-edit="${esc(trip.id)}">编辑行程</button></div><div class="trip-record-stops">${trip.stops.map(stop=>{const pin=getPins().find(pin=>pin.id===stop.pinId);return `<div>${pin?`<a href="${esc(placeGuideHref(pin))}" data-i18n-skip>${esc(stop.title)}</a>`:`<strong data-i18n-skip>${esc(stop.title)}</strong>`}<span class="trip-stop-score" aria-label="${stop.rating} / 5">${'★'.repeat(stop.rating)}<i>${'☆'.repeat(5-stop.rating)}</i></span></div>`;}).join('')}</div></article>`).join(''):'<p class="trip-empty">还没有行程，记录下一段故事。</p>';}
  function drawName(){panel.querySelector('[data-trip-name]').textContent=`${form.elements.year.value||'年份'} · ${form.elements.region.value||'地区'}`;}
  function drawStops(){stopsHost.innerHTML=draft.stops.map((stop,index)=>`<div class="trip-draft-stop"><div><strong data-i18n-skip>${esc(stop.pin.title)}</strong><button type="button" data-trip-stop-remove="${index}" aria-label="移除城市">×</button></div><div class="trip-score-stars" role="group" aria-label="${esc(stop.pin.title)}，推荐评分">${Array.from({length:5},(_,i)=>`<button type="button" data-trip-score="${index}" data-value="${i+1}" class="${i<stop.rating?'is-filled':''}" aria-pressed="${stop.rating===i+1}" aria-label="${i+1} 分">★</button>`).join('')}<span>${stop.rating?`${stop.rating} / 5`:'请先评分'}</span></div></div>`).join('');}
  function drawChoices(){
    const pins=getPins().filter(pin=>pin.kind!=='country'),match=key(query.value.trim()),seen=new Set(draft.stops.map(stop=>stop.pin.id));choices=[];
    const items=[...pins.filter(pin=>!match||key(pin.title).includes(match)).map(pin=>({pin})),...localPlaceMatches(query.value,{kind:'world'},8).map(place=>({place})),...remote.map(place=>({place}))];
    for(const item of items){const pin=item.pin||findDestinationPin(item.place,pins)||{id:item.place.pinId,title:item.place.name,kind:'city',lat:item.place.lat,lon:item.place.lon,note:'',status:'want',guides:[],...(item.place.countryHint?{countryHint:item.place.countryHint}:{})};if(seen.has(pin.id))continue;seen.add(pin.id);choices.push({pin,subtitle:item.place?.subtitle||''});if(choices.length>=12)break;}
    results.innerHTML=choices.map((choice,index)=>`<button type="button" data-trip-city-add="${index}"><span><strong data-i18n-skip>${esc(choice.pin.title)}</strong>${choice.subtitle?`<small data-i18n-skip>${esc(choice.subtitle)}</small>`:''}</span><span>＋</span></button>`).join('');
  }
  function open(trip){if(trip?.stops.some(stop=>!getPins().some(pin=>pin.id===stop.pinId))){message.textContent='有城市已取消标记，请先重新加入地图再编辑这段行程。';return;}controller?.abort();revision++;remote=[];draft={id:trip?.id||crypto.randomUUID(),stops:(trip?.stops||[]).map(stop=>{const pin=getPins().find(pin=>pin.id===stop.pinId);return pin?{pin,rating:stop.rating}:null;}).filter(Boolean)};form.elements.year.value=trip?.year||new Date().getFullYear();form.elements.region.value=trip?.region||'';query.value='';feedback.textContent='';panel.querySelector('#trip-dialog-title').textContent=trip?'编辑行程':'新建行程';drawName();drawStops();drawChoices();dialog.showModal();form.elements.region.focus();}
  function close(){if(saving)return;controller?.abort();revision++;dialog.close();}
  async function search(){const value=query.value.trim();if(!value)return;controller?.abort();controller=new AbortController();const own=++revision;feedback.textContent='正在寻找这个地方…';try{const places=await searchOnlinePlaces(value,{signal:controller.signal});if(stopped||own!==revision)return;remote=places;drawChoices();feedback.textContent=places.length?'':'没有找到更多地点。试试加上城市名，或使用英文名。';}catch(error){if(!stopped&&own===revision&&error.name!=='AbortError')feedback.textContent=error.message;}}
  function onClick(event){
    if(event.target.closest('[data-trip-new]')){open();return;}const edit=event.target.closest('[data-trip-edit]');if(edit){open(getTravelTrips().find(trip=>trip.id===edit.dataset.tripEdit));return;}
    if(event.target.closest('[data-trip-close]')){close();return;}if(event.target.closest('[data-trip-search]')){void search();return;}if(saving)return;
    const add=event.target.closest('[data-trip-city-add]');if(add){const choice=choices[Number(add.dataset.tripCityAdd)];if(!choice||draft.stops.some(stop=>stop.pin.id===choice.pin.id))return;draft.stops.push({pin:choice.pin,rating:0});drawStops();drawChoices();feedback.textContent='请为每个城市点击 1 至 5 星评分。';stopsHost.lastElementChild.querySelector('button[data-trip-score]')?.focus();return;}
    const score=event.target.closest('[data-trip-score]');if(score){const stop=draft.stops[Number(score.dataset.tripScore)];if(stop){stop.rating=Number(score.dataset.value);drawStops();feedback.textContent='';}return;}
    const remove=event.target.closest('[data-trip-stop-remove]');if(remove){draft.stops.splice(Number(remove.dataset.tripStopRemove),1);drawStops();drawChoices();}
  }
  function onInput(event){if(event.target===query){controller?.abort();revision++;remote=[];drawChoices();}else drawName();}
  function onKey(event){if(event.target===query&&event.key==='Enter'){event.preventDefault();void search();}}
  function onCancel(event){if(saving)event.preventDefault();else{controller?.abort();revision++;}}
  async function onSubmit(event){event.preventDefault();if(saving||!form.reportValidity())return;saving=true;save.disabled=true;try{const result=await commitTravelTrip({...draft,year:Number(form.elements.year.value),region:form.elements.region.value},{getPins,savePin:onSave});if(stopped)return;dialog.close();drawList();onChanged();message.textContent=result.saved?'行程已保存，城市与推荐评分已同步。':'行程暂存在本页，浏览器未能保存。请导出地图备份。';}catch(error){if(!stopped)feedback.textContent=error.message;}finally{saving=false;save.disabled=false;}}
  function onStorage(event){if(event.key==='tobias.travel-trips.v1'||event.key===null)drawList();}
  panel.addEventListener('click',onClick);form.addEventListener('input',onInput);form.addEventListener('keydown',onKey);form.addEventListener('submit',onSubmit);dialog.addEventListener('cancel',onCancel);window.addEventListener('storage',onStorage);drawList();
  return ()=>{stopped=true;controller?.abort();revision++;panel.removeEventListener('click',onClick);form.removeEventListener('input',onInput);form.removeEventListener('keydown',onKey);form.removeEventListener('submit',onSubmit);dialog.removeEventListener('cancel',onCancel);window.removeEventListener('storage',onStorage);if(dialog.open)dialog.close();};
}
